def greedy(logits: list) -> int:
    """Return the index of the highest-scoring token (greedy decoding)."""
    best = 0
    for i, v in enumerate(logits):
        if v > logits[best]:
            best = i
    return best

print(greedy([1.0, 3.0, 2.0, 0.5]))

def top_k_indices(logits: list, k: int) -> list:
    """Return the indices of the k highest logits, sorted ascending."""
    ranked = sorted(range(len(logits)), key=lambda i: logits[i], reverse=True)
    return sorted(ranked[:k])

print(top_k_indices([1.0, 3.0, 2.0, 0.5], 2))
